// Exact originals from the independently audited archive, not encodings
// reconstructed from the validator's schemas or tables.
func guidanceTestInflate(t *testing.T, s string) []byte {
	t.Helper()
	b, e := base64.StdEncoding.DecodeString(s)
	if e != nil {
		t.Fatal(e)
	}
	z, e := gzip.NewReader(bytes.NewReader(b))
	if e != nil {
		t.Fatal(e)
	}
	b, e = io.ReadAll(io.LimitReader(z, 8<<20))
	if e != nil {
		t.Fatal(e)
	}
	if e = z.Close(); e != nil {
		t.Fatal(e)
	}
	if len(b) == 8<<20 {
		t.Fatal("fixture bound")
	}
	return b
}

// guidanceTestInputsCache holds the decoded originals, inflated once per test
// process; it is never changed after it is filled.
var guidanceTestInputsCache struct {
	sync.Mutex
	data map[string]string
}

// guidanceTestInputs returns the caller's own map of the original encodings.
// Strings are immutable, so a copy of the map is a complete copy.
func guidanceTestInputs(t *testing.T) map[string]string {
	t.Helper()
	c := &guidanceTestInputsCache
	c.Lock()
	defer c.Unlock()
	if c.data == nil {
		v := map[string]string{}
		if e := json.Unmarshal(guidanceTestInflate(t, guidanceOriginalInputsGzip), &v); e != nil {
			t.Fatal(e)
		}
		c.data = v
	}
	return maps.Clone(c.data)
}
func guidanceTestValue(t *testing.T, p string) map[string]any {
	t.Helper()
	v, e := canonjson.DecodeObject([]byte(guidanceTestInputs(t)[p]))
	if e != nil {
		t.Fatal(e)
	}
	return v
}
func guidanceTestBytes(t *testing.T, v any) []byte {
	t.Helper()
	b, e := canonjson.MarshalFile(v)
	if e != nil {
		t.Fatal(e)
	}
	return b
}
func TestCatalogGuidanceInputOriginals(t *testing.T) {
	for p, k := range guidanceInputKinds() {
		t.Run(p, func(t *testing.T) {
			raw := []byte(guidanceTestInputs(t)[p])
			v, e := ParseCatalogGuidanceInputEncoding(k, raw)
			if e != nil {
				t.Fatal(e)
			}
			if v.Kind() != k || !bytes.Equal(v.Encoding(), raw) {
				t.Fatal("encoding/branch")
			}
			copyRaw := bytes.Clone(raw)
			raw[0] = '!'
			got := v.Encoding()
			got[0] = '!'
			if !bytes.Equal(v.Encoding(), copyRaw) {
				t.Fatal("mutable value")
			}
		})
	}
	if e := ValidateCatalogGuidanceInputEncoding("unknown", []byte("{}\n")); e == nil {
		t.Fatal("unknown kind")
	}
	if e := ValidateCatalogGuidanceInputEncoding("", nil); e == nil {
		t.Fatal("zero kind")
	}
	if (CatalogGuidanceInput{}).Encoding() != nil {
		t.Fatal("zero value authority")
	}
}
func TestCatalogGuidanceInputAuthoritativeSchemas(t *testing.T) {
	raw := guidanceTestInflate(t, guidanceOriginalSchemasGzip)
	if digestOf(raw) != "f097805b008917b152c7976f31749397df96ea2c4af408d0d5280648827cebf6" {
		t.Fatal("authoritative schema pin")
	}
	v, e := canonjson.DecodeObject(raw)
	if e != nil {
		t.Fatal(e)
	}
	s := catalogObject(v["schemas"])
	for name, actual := range guidanceSchemas {
		if !catalogEqual(actual, s[name]) {
			t.Fatal("frozen schema mismatch", name)
		}
	}
	raw = guidanceTestInflate(t, guidanceOriginalInventoriesGzip)
	if digestOf(raw) != "b5a015d9561bd14db649e28b57d290ca850a2fba66bce3a603499730c8914e9d" {
		t.Fatal("inventory pin")
	}
	v, e = canonjson.DecodeObject(raw)
	if e != nil {
		t.Fatal(e)
	}
	for inventory, schema := range map[string]string{"overlay_owner_v5": "overlay_owner_v5", "overlay_request_v4": "overlay_request_v4", "overlay_summary_v4": "overlay_summary_v4", "shared_receipt_v5": "shared_receipt_v5"} {
		props := catalogObject(catalogObject(s[schema])["properties"])
		keys := catalogArray(v[inventory])
		if len(props) != len(keys) {
			t.Fatal("inventory size", inventory)
		}
		for _, k := range keys {
			if _, ok := props[k.(string)]; !ok {
				t.Fatal("inventory key", k)
			}
		}
	}
}
func TestCatalogGuidanceInputEveryClosedField(t *testing.T) {
	t.Parallel()
	count := 0
	for p, k := range guidanceInputKinds() {
		base := guidanceTestValue(t, p)
		var paths [][]catalogTestStep
		catalogObjectPaths(base, nil, &paths)
		for i, path := range paths {
			for key := range catalogTestAt(base, path) {
				for _, mutation := range []string{"missing", "null", "bool", "wrong-type", "duplicate"} {
					t.Run(fmt.Sprintf("%s/object%d/%s/%s", p, i, key, mutation), func(t *testing.T) {
						t.Parallel()
						v := guidanceTestValue(t, p)
						o := catalogTestAt(v, path)
						raw := []byte(nil)
						switch mutation {
						case "missing":
							delete(o, key)
						case "null":
							o[key] = nil
						case "bool":
							o[key] = true
						case "wrong-type":
							if _, ok := o[key].(string); ok {
								o[key] = json.Number("7")
							} else {
								o[key] = "wrong"
							}
						case "duplicate":
							// Encode the whole valid document, then duplicate this exact key.
							raw = guidanceTestBytes(t, v)
							needle := []byte(fmt.Sprintf("%q:", key))
							at := bytes.Index(raw, needle)
							if at < 0 {
								t.Fatal("key not found")
							}
							raw = append(append(bytes.Clone(raw[:at]), []byte(fmt.Sprintf("%q: null, ", key))...), raw[at:]...)
						}
						if raw == nil {
							raw = guidanceTestBytes(t, v)
						}
						if e := ValidateCatalogGuidanceInputEncoding(k, raw); e == nil {
							t.Fatal("field mutation accepted")
						}
					})
					count++
				}
			}
			t.Run(fmt.Sprintf("%s/object%d/unknown", p, i), func(t *testing.T) {
				t.Parallel()
				v := guidanceTestValue(t, p)
				catalogTestAt(v, path)["unexpected"] = json.Number("1")
				if e := ValidateCatalogGuidanceInputEncoding(k, guidanceTestBytes(t, v)); e == nil {
					t.Fatal("unknown nested key")
				}
			})
		}
	}
	t.Logf("independent closed-field mutations: %d", count)
}
func TestCatalogGuidanceInputSemanticRefusals(t *testing.T) {
	cases := []struct {
		p    string
		edit func(map[string]any)
	}{
		{"inputs/tool-guidance-manifest.json", func(v map[string]any) { r := catalogArray(v["records"]); r[0], r[1] = r[1], r[0] }},
		{"inputs/tool-guidance-manifest.json", func(v map[string]any) { catalogArray(v["records"])[1] = catalogArray(v["records"])[0] }},
		{"inputs/tool-guidance-manifest.json", func(v map[string]any) { catalogObject(catalogArray(v["records"])[0])["path"] = "../outside.json" }},
		{"inputs/tool-guidance-manifest.json", func(v map[string]any) {
			catalogObject(catalogArray(v["records"])[0])["path"] = "guidance//fixture-cli.json"
		}},
		{"inputs/tool-guidance/huyang.json", func(v map[string]any) { v["capability_ids"] = []any{"file-read"} }},
		{"inputs/tool-guidance/huyang.json", func(v map[string]any) {
			catalogObject(v["help"])["kind"] = "executable"
			catalogObject(v["help"])["argv"] = []any{"huyang", "--help"}
		}},
		{"inputs/tool-guidance/huyang.json", func(v map[string]any) { catalogObject(v["owner"])["status"] = "approved" }},
		{"inputs/tool-guidance/huyang.json", func(v map[string]any) { catalogObject(catalogArray(v["rules"])[0])["id"] = "huyang.unknown.v1" }},
		{"inputs/tool-guidance/huyang.json", func(v map[string]any) { v["workflow"] = []any{} }},
		{"inputs/tool-guidance/huyang.json", func(v map[string]any) {
			catalogObject(catalogArray(v["rules"])[0])["evidence_quote_sha256"] = strings.Repeat("0", 64)
		}},
		{"inputs/required-global-policy.json", func(v map[string]any) { catalogObject(v["deferred_owner_seam"])["status"] = "ready" }},
		{"inputs/required-global-policy.json", func(v map[string]any) { catalogObject(v["deferred_owner_seam"])["required_rules"] = []any{} }},
		{"inputs/required-global-policy.json", func(v map[string]any) { catalogObject(v["texts"])["shared"] = "source is present; proceed" }},
		{"inputs/guidance-profile.json", func(v map[string]any) { catalogObject(catalogArray(v["tools"])[0])["authorized"] = "granted" }},
		{"inputs/guidance-profile.json", func(v map[string]any) { catalogObject(catalogArray(v["tools"])[0])["availability"] = "ready" }},
		{"inputs/guidance-profile.json", func(v map[string]any) { catalogObject(catalogArray(v["tools"])[0])["enforced"] = "qualified" }},
		{"inputs/guidance-profile.json", func(v map[string]any) { v["scope"] = "runtime" }},
		{"inputs/guidance-profile.json", func(v map[string]any) { r := catalogArray(v["tools"]); r[1] = r[0] }},
		{"inputs/guidance-observation.json", func(v map[string]any) { v["source_commit"] = strings.Repeat("0", 40) }},
		{"inputs/guidance-observation.json", func(v map[string]any) {
			d := catalogObject(catalogObject(v["source_reads"])["data"])
			r := catalogArray(d["files"])
			r[1] = r[0]
		}},
		{"inputs/guidance-observation.json", func(v map[string]any) {
			r := catalogObject(catalogArray(catalogObject(catalogObject(v["source_reads"])["data"])["files"])[0])
			r["content"] = r["content"].(string) + "# substitution\n"
		}},
		{"inputs/guidance-observation.json", func(v map[string]any) {
			r := catalogObject(catalogArray(catalogObject(catalogObject(v["descriptor_reads"])["data"])["entries"])[0])
			r["bytes"] = json.Number("507")
		}},
		{"inputs/guidance-layout.json", func(v map[string]any) {
			catalogObject(v["texts"])["shared"] = "{{GLOBAL_SHARED}}{{FRAGMENTS}}{{MODEL_CODEX}}{{DISCOVERY}}{{UNKNOWN}}"
		}},
		{"inputs/guidance-layout.json", func(v map[string]any) {
			catalogObject(v["texts"])["shared"] = "{{GLOBAL_SHARED}}{{FRAGMENTS}}{{MODEL_CODEX}}{{DISCOVERY}}{"
		}},
		{"inputs/guidance-layout.json", func(v map[string]any) { catalogObject(v["bindings"])["imported_owner_sha256"] = "not-hex" }},
	}
	for i, c := range cases {
		t.Run(fmt.Sprintf("%d", i), func(t *testing.T) {
			v := guidanceTestValue(t, c.p)
			c.edit(v)
			if e := ValidateCatalogGuidanceInputEncoding(guidanceInputKinds()[c.p], guidanceTestBytes(t, v)); e == nil {
				t.Fatal("semantic mutation accepted")
			}
		})
	}
}
func TestCatalogGuidanceInputEncodingBounds(t *testing.T) {
	p := "inputs/guidance-profile.json"
	raw := []byte(guidanceTestInputs(t)[p])
	k := CatalogGuidanceProfile
	for name, b := range map[string][]byte{
		"BOM": append([]byte{0xef, 0xbb, 0xbf}, raw...), "invalid-UTF8": append(bytes.Clone(raw), 0xff), "trailing": append(bytes.Clone(raw), []byte("{}")...),
		"whitespace": append([]byte(" "), raw...), "NUL": bytes.Replace(raw, []byte("fixture-only"), []byte("fixture\\u0000only"), 1),
		"surrogate": bytes.Replace(raw, []byte("fixture-only"), []byte("\\ud800"), 1), "oversize": bytes.Repeat([]byte(" "), 262145),
	} {
		t.Run(name, func(t *testing.T) {
			if e := ValidateCatalogGuidanceInputEncoding(k, b); e == nil {
				t.Fatal("bad encoding")
			}
		})
	}
	for _, version := range []string{"true", "null", "1.0", "1e0", "0", "2"} {
		b := bytes.Replace(raw, []byte("\"schema_version\": 1"), []byte("\"schema_version\": "+version), 1)
		if e := ValidateCatalogGuidanceInputEncoding(k, b); e == nil {
			t.Fatal("version", version)
		}
	}
	for _, n := range []int{65536, 65537} {
		v := guidanceTestValue(t, p)
		v["snapshot_id"] = strings.Repeat("x", n)
		e := ValidateCatalogGuidanceInputEncoding(k, guidanceTestBytes(t, v))
		if (e == nil) != (n == 65536) {
			t.Fatal("text boundary", n, e)
		}
	}
	if e := ValidateCatalogGuidanceInputEncoding(CatalogGuidanceLayout, bytes.Repeat([]byte(" "), 131073)); e == nil {
		t.Fatal("layout bound")
	}
	// Isolate conjunctive scalar resource predicates where the closed finite
	// grammars already impose stricter cardinality/depth limits.
	for _, n := range []int{1024, 1025} {
		v := map[string]any{"a": make([]any, n)}
		for i := range v["a"].([]any) {
			v["a"].([]any)[i] = "x"
		}
		e := snapshotCanonical(guidanceTestBytes(t, v))
		if (e == nil) != (n == 1024) {
			t.Fatal("container bound", n, e)
		}
	}
	// The owning predicate counts the scalar leaf as an additional level.
	for _, n := range []int{11, 12} {
		var v any = "x"
		for i := 0; i < n; i++ {
			v = map[string]any{"a": v}
		}
		e := snapshotCanonical(guidanceTestBytes(t, v))
		if (e == nil) != (n == 11) {
			t.Fatal("depth bound", n, e)
		}
	}
}
func TestCatalogGuidanceInputNonGrantLabels(t *testing.T) {
	for _, availability := range []string{"observed", "unavailable", "unknown"} {
		for _, visibility := range []string{"visible", "hidden"} {
			for _, authorized := range []string{"unknown", "denied", "declaration-only"} {
				v := guidanceTestValue(t, "inputs/guidance-profile.json")
				r := catalogObject(catalogArray(v["tools"])[1])
				r["availability"] = availability
				r["visibility"] = visibility
				r["authorized"] = authorized
				if e := ValidateCatalogGuidanceInputEncoding(CatalogGuidanceProfile, guidanceTestBytes(t, v)); e != nil {
					t.Fatal(e)
				}
			}
		}
	}
}

